        }

else if( xSecureContexts[ i ].pvTaskHandle == pvTaskHandle ) {
            /* A task can only have one secure context. Do not allocate a second
             * context for the same task. */
            ulSecureContextIndex = secureconfigMAX_SECURE_CONTEXTS;
