                          alt_isr_func isr,
                          void * isr_context,
                          void * flags ) {
    int rc = -EINVAL;
    alt_irq_context status;
    int id = irq; /* IRQ interpreted as the interrupt ID. */

    if( id < ALT_NIRQ )
